/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useEffect, useMemo } from 'react'
import { connect } from 'react-redux'
import {
  Card,
  Button,
  Upload,
  Icon,
  Spin,
  message,
  Row,
  Alert,
  Select,
  Form,
  Input,
  notification,
  InputNumber
} from 'antd'
import PropTypes from 'prop-types'
import { LayoutWrapper } from './index.style'
import UploadAction from '../../../../redux/policy/actions'
// import { createCSV } from '../../../../helpers/utility'
import { downloadDataFromUrl } from './constant'

const { uploadBulkPolicyRetryEnqueue, bulkOperationTypes, bulkInternalCancellation, bulkCancellation, buldPremiumUpdate, uploadCsvFile, bulkOperate, resetReduxState } = UploadAction

const { Dragger } = Upload
function BulkRetryPolicies (props) {
  const [optionValue, setOptionValue] = useState()

  const { uploadCsvMessage, uploadCsvData, resetReduxState, bulkInternalCancellationMessage, bulkCancellationMessage, bulkUpdatePremiumMessage, profileData,bulkOperateUploadMessage, bulkOperationsTypesMessage, bulkOperationsTypesData } = props

  useEffect(() => {
    props.bulkOperationTypes()
    resetReduxState(['bulkOperationsTypesMessage'])
    resetReduxState(['bulkOperationsTypesData'])
  },[])

  const bulkOperType = useMemo(() => { 
    if(bulkOperationsTypesMessage === 'success' && bulkOperationsTypesMessage !== ''){
      setOptionValue(bulkOperationsTypesData[0].code)
    }
    return(
    bulkOperationsTypesData )}, [bulkOperationsTypesMessage])

  useEffect(() => {
    if (uploadCsvMessage === 'success' && uploadCsvMessage !== '') {
      const { url } = uploadCsvData

      if (!url) {
        notification.error({
          message: uploadCsvMessage || 'Failed To fetch Data'
        })

        return
      }
      
      const formValues = form.getFieldsValue()
      props.bulkOperate({
        body: {
          ...formValues,
          file_url: url,
          file_name: `${optionValue}.csv`,
          operation_type: optionValue
        }
      })
      // if (optionValue === 'bulk_internal_cancellation') {
      //   props.bulkInternalCancellation({
      //     body: {
      //       ...formValues,
      //       file_url: url
      //     }
      //   })
      // } else if (optionValue === 'bulk_cancellation') {
      //   props.bulkCancellation({
      //     body: {
      //       ...formValues,
      //       file_url: url
      //     }
      //   })
      // } else if (optionValue === 'bulk_update_premium') {
      //   props.buldPremiumUpdate({
      //     body: {
      //       ...formValues,
      //       file_url: url
      //     }
      //   })
      // }
    }
  }, [uploadCsvMessage, uploadCsvData])

  useEffect(() => {
    if(bulkOperateUploadMessage === 'success'){
      notification.success(
        {
          message: 'file uploaded successfully!'
        }
      )
      resetReduxState(['uploadCsvMessage'])
      resetReduxState(['uploadCsvData'])
      resetReduxState(['bulkOperateUploadMessage'])

    }else if(bulkOperateUploadMessage !== 'success' && bulkOperateUploadMessage !== ''){
      notification.error(
        {
          message: `Error while uploading file: ${bulkOperateUploadMessage}`
        }
      )
      resetReduxState(['uploadCsvMessage'])
      resetReduxState(['uploadCsvData'])
      resetReduxState(['bulkOperateUploadMessage'])
    }

  }, [bulkOperateUploadMessage])

  useEffect(() => {
    if (bulkInternalCancellationMessage === 'success') {
      notification.success({
        message: bulkInternalCancellationMessage
      })
    } else if (bulkInternalCancellationMessage !== 'success' && bulkInternalCancellationMessage !== '') {
      notification.error({
        message: bulkInternalCancellationMessage
      })
    }
    resetReduxState(['bulkInternalCancellationMessage'])
  }, [bulkInternalCancellationMessage])

  useEffect(() => {
    if (bulkCancellationMessage === 'success') {
      notification.success({
        message: bulkCancellationMessage
      })
    } else if (bulkCancellationMessage !== 'success' && bulkCancellationMessage !== '') {
      notification.error({
        message: bulkCancellationMessage
      })
    }
    resetReduxState(['bulkCancellationMessage'])
  }, [bulkCancellationMessage])

  useEffect(() => {
    if (bulkUpdatePremiumMessage === 'success') {
      notification.success({
        message: bulkUpdatePremiumMessage
      })
    } else if (bulkUpdatePremiumMessage !== 'success' && bulkUpdatePremiumMessage !== '') {
      notification.error({
        message: bulkUpdatePremiumMessage
      })
    }
    resetReduxState(['bulkUpdatePremiumMessage'])
  }, [bulkUpdatePremiumMessage])

  const customRequest = ({ file }) => {
    const { type } = file
    const isGt100MB = file.size / 1024 / 1024 > 100
    if (['text/csv'].includes(type)) {
      const formData = new FormData()
      formData.append('file', file)
      
      if (isGt100MB) {    
        message.error('Note: Maximum allowed file size is 100Mb')
      } else {
        props.uploadCsvFile({ body: formData })
      }   
    } else {
      message.error('Incorrect file type, please upload only .csv')
    }
  }

  const checkDisabledCondition = () => {
    if (optionValue === 'bulk_internal_cancellation') {
      const val = props.form.getFieldValue('reason')
      return !val
    }
    return false
  }

  const { uploadMessageLoading, uploadMessageError, form } = props

  const { getFieldDecorator } = form

  const handleSampleDownload = () => {
    let download_link
    if(optionValue){
      download_link = bulkOperType.filter(value => optionValue === value.code)
      download_link = download_link[0].sample_file
    }     
    downloadDataFromUrl(download_link) 
  }

  return (
    <LayoutWrapper>
      <Card style={{ width: '100%' }}>
        <Spin tip='Uploading...' spinning={false}>
          <div className='header'>
            <section className='bulk-container'>
              <Select
                className='bulk-option'
                value={optionValue}
                onChange={(val) => setOptionValue(val)}
              >
                {bulkOperType && (
                  bulkOperType.map(packet => {
                    return (
                      <Select.Option value={packet.code}>{packet.name}</Select.Option>
                    )
                  })
                )}
              </Select>
            </section>

            <Button
              type='primary'
              onClick={handleSampleDownload}
              className='csv-sample-button'
            >
              Download Sample
            </Button>
          </div>
          {!uploadMessageLoading && uploadMessageError && (
            <Alert closable message='File Failed to upload' type='error' />
          )}
          {uploadMessageLoading !== undefined && !uploadMessageLoading && (
            <Alert
              closable
              message='File Uploaded Successfully'
              type='success'
            />
          )}

          <Row className='mT-20'>
            <Spin
              spinning={
                uploadMessageLoading !== undefined && uploadMessageLoading
              }
            >
              <Form>
                  <section className='form-container'>
                    <Form.Item label='Reason'>
                      {getFieldDecorator('reason', {
                        rules: [
                          {
                            required: true,
                            message: 'Reason Is Required'
                          }
                        ]
                      })(<Input />)}
                    </Form.Item>

                    <Form.Item label='Batch Size'>
                      {getFieldDecorator('batch_size', {
                        initialValue:0,
                        rules: [
                          {
                            required: false,
                            message: 'Reason Is Required'
                          }
                        ]
                      })(<InputNumber />)}
                    </Form.Item>
                    <Form.Item label='User'>
                      {getFieldDecorator('user', {
                        rules: [
                          {
                            required: true,
                          }
                        ],
                        initialValue : profileData.email 
                      })(<Input type='text' disabled />)}
                    </Form.Item>
                  </section>
              </Form>

              <Dragger
                name='file'
                showUploadList={false}
                multiple={false}
                customRequest={(val) => customRequest(val)}
                disabled={checkDisabledCondition()}
              >
                <div>
                  <p className='ant-upload-drag-icon'>
                    <Icon type='inbox' />
                  </p>
                  <p className='ant-upload-text'>
                    Click or drag file to this area to upload
                  </p>
                </div>
              </Dragger>
            </Spin>
          </Row>
        </Spin>
      </Card>
    </LayoutWrapper>
  )
}

BulkRetryPolicies.propTypes = {
  templateList: PropTypes.array.isRequired
}

BulkRetryPolicies.defaultProps = {
  templateList: []
}

export default connect(
  (state) => ({
    uploadMessage: state.Policy.uploadBulkRetryMessage,
    uploadMessageLoading: state.Loading.UPLOAD_BULK_POLICY_RETRY_NOTIFICATION,
    uploadMessageError: state.Error.UPLOAD_BULK_POLICY_RETRY_NOTIFICATION,

    bulkInternalCancellationMessage: state.Policy.bulkInternalCancellationMessage,
    profileData: state.Auth.profile,
    uploadCsvMessage: state.Policy.uploadCsvMessage,
    uploadCsvData: state.Policy.uploadCsvData,

    bulkCancellationMessage: state.Policy.bulkCancellationMessage,
    bulkUpdatePremiumMessage: state.Policy.bulkUpdatePremiumMessage,

    bulkOperateUploadMessage: state.Policy.bulkOperateUploadMessage,

    bulkOperationsTypesData: state.Policy.bulkOperationsTypesData,
    bulkOperationsTypesMessage: state.Policy.bulkOperationsTypesMessage,
  }),
  {
    uploadBulkPolicyRetryEnqueue,
    bulkOperationTypes,
    bulkInternalCancellation,
    buldPremiumUpdate,
    bulkCancellation,
    uploadCsvFile,
    bulkOperate,
    resetReduxState
  }
)(Form.create({})(BulkRetryPolicies))
